entries.commands:
! ===== 静态路由（锐捷 RGOS）=====
enable
configure terminal
ip route {{dest_net}} {{mask}} {{next_hop}}
ip route 0.0.0.0 0.0.0.0 {{next_hop}}
ip route {{dest_net}} {{mask}} {{backup_hop}} {{distance}}
end
write
show ip route

! ===== OSPF 基本配置（锐捷 RGOS）=====
enable
configure terminal
router ospf {{process_id}}
 router-id {{router_id}}
 network {{network}} {{wildcard}} area {{area_id}}
 passive-interface {{passive_port}}
 exit
end
write
show ip ospf neighbor
show ip route ospf

! ===== 扩展 ACL 配置与下发（锐捷 RGOS）=====
enable
configure terminal
ip access-list extended {{acl_name}}
 permit ip {{src_net}} {{src_wild}} {{dst_net}} {{dst_wild}}
 deny ip any any
 exit
interface GigabitEthernet {{port}}
 ip access-group {{acl_name}} in
 exit
end
write
show ip access-lists {{acl_name}}

! ===== NAT / PAT 配置（锐捷 RGOS）=====
enable
configure terminal
interface GigabitEthernet {{inside_port}}
 ip address {{inside_ip}} {{inside_mask}}
 ip nat inside
 exit
interface GigabitEthernet {{outside_port}}
 ip address {{outside_ip}} {{outside_mask}}
 ip nat outside
 exit
access-list {{acl_number}} permit {{src_net}} {{src_wild}}
ip nat inside source list {{acl_number}} interface GigabitEthernet {{outside_port}} overload
! 静态一对一映射
ip nat inside source static {{inside_server}} {{public_ip}}
end
write
show ip nat translations
